namespace Lycoris.Tweaks;

/// <summary>
/// Official sources behind every tweak (roadmap item 10). Each URL was opened and checked against what the tweak changes
/// on the review date; an empty list means no official page exists and the basis is Lycoris's research (docs/research).
/// Re-check the pages and move the date before it is a year old (TweakSourcesTests fails otherwise).
/// </summary>
public static class TweakSources
{
    private static readonly DateOnly Reviewed = new(2026, 11, 4);

    private static TweakEvidence E(string basis, string windows, string limits, params string[] urls) => new(basis, windows, limits, Reviewed, urls);

