        ["news-interests-off"] = () => E(Loc.T("Microsoft документирует политику FeedsEnabled; значение 0 полностью отключает «Новости и интересы» на панели задач."), "Windows 10 (Pro, Business, Enterprise, Education)", Loc.T("На Windows 11 и в Home политика не поддерживается."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-feeds"),
        ["notepad-ai-off"] = () => E(Loc.T("Microsoft документирует политику DisableAIFeaturesInNotepad (значение DisableAIFeatures=1 в HKLM\\SOFTWARE\\Policies\\WindowsNotepad)."), "Windows 11 22H2+ (Notepad 11.2503.16.0+)", Loc.T("Нужна версия Блокнота 11.2503.16.0 или новее."), "https://learn.microsoft.com/en-us/windows/client-management/manage-notepad"),
