        ["pcie-aspm-off"] = () => E(Loc.T("Microsoft: параметр «Управление питанием состояния связи» (ASPM) принимает значения Off, Moderate и Maximum; индекс 0 означает «Выкл»."), "Windows 10, 11", "", "https://learn.microsoft.com/en-us/windows-hardware/design/component-guidelines/power-management-for-storage-hardware-devices-nvme"),
        ["power-mode-best-efficiency-ac"] = () => E(Loc.T("Microsoft: режим «Максимальная эффективность» (GUID 961cc777-...) смещает баланс к экономии энергии, ограничивая фоновую активность."), "Windows 11", Loc.T("Режим может быть переопределён другими сигналами системы."), "https://learn.microsoft.com/en-us/windows/win32/api/powrprof/nf-powrprof-powersetuserconfiguredacpowermode", "https://support.microsoft.com/en-us/windows/experience/power-battery/power-settings-in-windows-11"),
        ["power-mode-best-efficiency-dc"] = () => E(Loc.T("Microsoft описывает режим «Максимальная эффективность» (Best power efficiency), отдельно для работы от батареи и от сети."), "Windows 10, 11", Loc.T("Режим может быть недоступен при пользовательской схеме питания; нужна схема «Сбалансированная»."), "https://support.microsoft.com/en-us/windows/change-the-power-mode-for-your-windows-pc-c2aff038-22c9-f46d-5ca0-78696fdf2de8", "https://support.microsoft.com/en-us/windows/power-settings-in-windows-11-0d6a2b6b-2e87-4611-9980-ac9ea2175734"),
        ["power-mode-best-performance"] = () => E(Loc.T("Microsoft: в Windows 11 есть режим питания «Максимальная производительность» (GUID ded574b5-...), смещающий баланс к производительности."), "Windows 11", Loc.T("Выбор пользователя может быть переопределён другими сигналами системы."), "https://learn.microsoft.com/en-us/windows/win32/api/powrprof/nf-powrprof-powersetuserconfiguredacpowermode", "https://learn.microsoft.com/en-us/windows-hardware/customize/desktop/customize-power-slider"),
        ["power-plan-balanced"] = () => E(Loc.T("Microsoft документирует схему «Сбалансированная»: автоматически балансирует производительность и энергопотребление по нагрузке."), "Windows 10, 11", Loc.T("На устройствах с Modern Standby доступна только сбалансированная схема или производные от неё."), "https://learn.microsoft.com/en-us/windows/win32/power/power-policy-settings"),
        ["power-plan-balanced-x3d"] = () => E(Loc.T("Официальной страницы AMD, которая открывалась бы при проверке, нет. По исследованию Lycoris драйвер чипсета AMD распределяет игры по ядрам с 3D V-Cache только при сбалансированной схеме."), "Windows 10, 11", ""),
        ["power-plan-performance"] = () => E(Loc.T("Microsoft документирует схему «Высокая производительность»: максимальная производительность ценой повышенного энергопотребления."), "Windows 10, 11", Loc.T("На устройствах с Modern Standby доступна только сбалансированная схема или производные от неё."), "https://learn.microsoft.com/en-us/windows/win32/power/power-policy-settings"),
        ["power-plan-ultimate"] = () => E(Loc.T("Microsoft не описывает схему «Максимальная производительность» для домашних ПК. Пункт только для экспертов: он копирует встроенный шаблон Windows и откатывается полностью."), "Windows 10, 11", ""),
        ["recall-snapshots-off"] = () => E(Loc.T("Microsoft документирует политику DisableAIDataAnalysis: значение 1 отключает сохранение снимков Recall и удаляет уже сохранённые."), "Windows 11 24H2 (26100.3915+) · Copilot+ PC", Loc.T("Recall есть только на Copilot+ PC; на остальных ПК политика ничего не меняет."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-windowsai", "https://learn.microsoft.com/en-us/windows/client-management/manage-recall"),
        ["remote-assistance-off"] = () => E(Loc.T("Microsoft документирует параметр fAllowToGetHelp: false запрещает пользователю запрашивать помощь через Удалённый помощник."), "Windows 10, 11", Loc.T("Быстрая помощь (Quick Assist) — отдельное приложение и этим параметром не отключается."), "https://learn.microsoft.com/en-us/windows-hardware/customize/desktop/unattend/microsoft-windows-remoteassistance-exe-fallowtogethelp", "https://support.microsoft.com/en-us/windows/apps/solve-pc-problems-remotely-with-remote-assistance"),
        ["screen-off-ac-10m"] = () => E(Loc.T("Microsoft: VIDEOIDLE задаёт простой до выключения экрана в секундах; в Windows 11 по умолчанию от сети экран гаснет через 5 минут."), "Windows 10, 11", "", "https://learn.microsoft.com/en-us/windows-hardware/customize/power-settings/display-settings-display-idle-timeout", "https://support.microsoft.com/en-us/windows/experience/power-battery/power-settings-in-windows-11"),
        ["search-highlights-off"] = () => E(Loc.T("Microsoft документирует политику AllowSearchHighlights, отключающую «подсветку» в поле поиска (косвенно)."), "Windows 10 20H2+ (KB5011543), 11", Loc.T("Политика уровня устройства для Pro/Enterprise/Education."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-search"),
        ["search-index-on-battery-off"] = () => E(Loc.T("Microsoft подтверждает групповую политику паузы индексирования при работе от батареи: индексирование завершится при подключении питания."), "Windows 10, 11", "", "https://learn.microsoft.com/en-us/troubleshoot/windows-client/shell-experience/windows-search-performance-issues"),
        ["sleep-ac-30m"] = () => E(Loc.T("Microsoft: STANDBYIDLE задаёт простой до сна в секундах; в Windows 11 по умолчанию от сети сон наступает через 5-15 минут."), "Windows 10, 11", "", "https://learn.microsoft.com/en-us/windows-hardware/customize/power-settings/sleep-settings-sleep-idle-timeout", "https://support.microsoft.com/en-us/windows/experience/power-battery/power-settings-in-windows-11"),
        ["spotlight-third-party-off"] = () => E(Loc.T("Microsoft документирует политику DisableThirdPartySuggestions (не предлагать стороннее содержимое в Windows spotlight)."), "Windows 10 1607+, 11", Loc.T("Другие рекомендации Microsoft остаются; Spotlight — Enterprise/Education."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-experience", "https://learn.microsoft.com/en-us/windows/configuration/windows-spotlight/"),
        ["start-hide-recommended"] = () => E(Loc.T("Microsoft документирует политику HideRecommendedSection, скрывающую раздел рекомендуемых файлов и приложений в «Пуске»."), "Windows 11 22H2+", Loc.T("Политика действует в Windows 11 22H2 и новее."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-start"),
        ["start-phone-panel-off"] = () => E(Loc.T("Microsoft описывает переключатель «Показывать мобильное устройство в меню Пуск» в Параметры → Персонализация → Пуск."), "Windows 11", Loc.T("Функция внедряется постепенно, переключатель может отсутствовать."), "https://support.microsoft.com/en-us/windows/apps/phonelink/mobile-device-in-start-menu"),
        ["startup-delay-off"] = () => E(Loc.T("Microsoft не документирует StartupDelayInMSec. Пункт убирает задержку перед автозагрузкой после входа; откат удаляет созданный ключ."), "Windows 10, 11", ""),
        ["start-web-recommendations-off"] = () => E(Loc.T("Microsoft документирует политику HideRecommendedPersonalizedSites для удаления персональных рекомендаций сайтов из «Пуска»."), "Windows 11 22H2 (KB5027303+)", Loc.T("Требуется Windows 11 22H2 с KB5027303 или новее."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-start"),
