        ["taskbar-end-task"] = () => E(Loc.T("Microsoft документирует «Завершить задачу» в меню значка панели задач, включаемое в параметрах разработчика."), "Windows 11 22H2 (KB5030310+)", "", "https://blogs.windows.com/windowsdeveloper/2023/09/26/new-experiences-designed-to-make-every-developer-more-productive-on-windows-11/"),
