        ["tcp-autotuning-normal"] = () => E(Loc.T("Microsoft описывает autotuninglevel: normal — значение по умолчанию, окно приёма растёт под почти любые сценарии."), "Windows 10, 11", Loc.T("Устройства, не поддерживающие масштабирование окна RFC 1323, могут давать сбои."), "https://learn.microsoft.com/ja-jp/archive/blogs/netgeeks/a-word-about-autotuninglevel-tcp-receive-auto-tuning-level-explained", "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2008-R2-and-2008/cc731258(v=ws.10)"),
