        ["trim-on"] = () => E(Loc.T("Microsoft описывает fsutil behavior disabledeletenotify: 0 включает уведомления об удалении (TRIM); для NTFS по умолчанию включено."), "Windows 10, 11", Loc.T("Некоторые устройства теряют скорость при включённом TRIM; перезагрузка не нужна."), "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/fsutil-behavior"),
