        ["visual-effects-performance"] = () => E(Loc.T("Microsoft советует «Обеспечить наилучшее быстродействие» для визуальных эффектов; SPI-параметры управляют анимациями."), "Windows 10, 11", "", "https://support.microsoft.com/en-us/windows/tips-to-improve-pc-performance-in-windows-b3b3ef5b-5953-fb6a-2528-4bbed82fba96", "https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-systemparametersinfoa"),
        ["vrr-optimization"] = () => E(Loc.T("Microsoft: параметр включает VRR для полноэкранных игр DirectX 11, которые не поддерживают его сами."), "Windows 11", Loc.T("Нужны подходящие драйверы и VRR-монитор."), "https://devblogs.microsoft.com/directx/navigating-the-redesigned-graphics-settings-page/"),
        ["wake-timers-important-only"] = () => E(Loc.T("Microsoft: у параметра «Разрешить таймеры пробуждения» (RTCWAKE) значение 2 «Important» означает пробуждение только по внутренним системным таймерам."), "Windows 10, 11", "", "https://learn.microsoft.com/en-us/windows-hardware/customize/power-settings/sleep-settings-automatically-wake-for-tasks"),
        ["widgets-off"] = () => E(Loc.T("Microsoft документирует политику AllowNewsAndInterests («Разрешить виджеты»); значение 0 отключает весь опыт виджетов."), "Windows 11 21H2+", Loc.T("Политика уровня устройства (Pro, Enterprise, Education)."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-newsandinterests"),
        ["wifi-power-saving-off"] = () => E(Loc.T("Intel: режим «Максимальная производительность» в параметрах беспроводного адаптера ставит скорость выше энергосбережения."), "Windows 10, 11", Loc.T("На батарее разряд идёт быстрее; Intel не советует менять настройки по умолчанию."), "https://www.intel.com/content/www/us/en/support/articles/000005879/wireless/legacy-intel-wireless-products.html"),
        ["win32-priority-programs"] = () => E(Loc.T("Это переключатель «Оптимизировать работу: программ» в окне «Параметры быстродействия» Windows. Lycoris ставит только это стандартное значение, другие числа отвергнуты исследованием."), "Windows 10, 11", ""),
        ["windowed-games-optimization"] = () => E(Loc.T("Microsoft: параметр переводит игры DX10/11 в оконном режиме на flip model, снижая задержку кадра и открывая VRR и Auto HDR."), "Windows 11", Loc.T("Не действует в полноэкранном режиме; игру нужно перезапустить."), "https://support.microsoft.com/en-us/windows/hardware/display-graphics/optimizations-for-windowed-games-in-windows-11", "https://devblogs.microsoft.com/directx/navigating-the-redesigned-graphics-settings-page/"),
        ["wu-active-hours"] = () => E(Loc.T("Microsoft документирует период активности: перезагрузки после обновлений происходят вне него, максимум 18 часов."), "Windows 10 1703+, 11", Loc.T("Период активности не действует, если включены политики «без автоперезагрузки при вошедших пользователях» или «всегда перезагружать»."), "https://learn.microsoft.com/en-us/windows/deployment/update/waas-restart"),
        ["wu-defer-feature-updates"] = () => E(Loc.T("Microsoft документирует отсрочку обновлений функций DeferFeatureUpdatesPeriodInDays: от 0 до 365 дней."), "Windows 10 1607+, 11", Loc.T("Если задана целевая версия, отсрочка не действует."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-update", "https://learn.microsoft.com/en-us/windows/deployment/update/waas-wufb-group-policy"),
        ["wu-exclude-drivers"] = () => E(Loc.T("Microsoft документирует политику ExcludeWUDriversInQualityUpdate (1 — не включать драйверы в обновления Windows)."), "Windows 10 1607+, 11", Loc.T("Microsoft рекомендует оставлять драйверы включёнными (по умолчанию), если вы не управляете ими вручную."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-update", "https://learn.microsoft.com/en-us/windows/deployment/update/waas-wufb-group-policy"),
        ["wu-target-version"] = () => E(Loc.T("Microsoft документирует политики ProductVersion и TargetReleaseVersion для закрепления версии Windows."), "Windows 10 2004+, 11", Loc.T("Через 60 дней после окончания обслуживания версии устройство обновится само; неверное значение блокирует обновления функций."), "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-update", "https://learn.microsoft.com/en-us/windows/deployment/update/waas-wufb-group-policy"),
